package com.neirofm.data
import java.util.Calendar
import kotlin.random.Random
data class RadioProgram(val name:String,val presenter:String,val description:String,val startHour:Int,val endHour:Int,val format:String)
object ProgramCatalog {
 val programs=listOf(
 RadioProgram("Neiro Утро","maria","Лёгкий старт, любопытные факты, планы и музыка",6,11,"утренний журнал"),
 RadioProgram("Дневная волна","alex","Истории технологий, науки, культуры и городов",11,17,"познавательное шоу"),
 RadioProgram("Вечерний маршрут","maria","Большие темы, разговорные подкасты и музыка",17,22,"вечернее авторское шоу"),
 RadioProgram("После полуночи","max","Атмосферные истории, загадки и спокойные размышления",22,6,"ночной разговор"))
 fun current(hour:Int=Calendar.getInstance().get(Calendar.HOUR_OF_DAY)):RadioProgram=programs.firstOrNull{if(it.startHour<it.endHour)hour in it.startHour until it.endHour else hour>=it.startHour||hour<it.endHour}?:programs.first()
 private val topics=listOf("Почему мы запоминаем музыку","Необычные места нашей планеты","Как рождаются привычки","История повседневных вещей","Загадки космоса","Города будущего","Почему нам снятся сны","Самые удивительные открытия науки","Как менялся мир звукозаписи","Маленькие радости обычного дня","Животные с невероятными способностями","Тайны океана","Архитектура, которая удивляет","Как работает человеческая память","Путешествие одной мелодии","Изобретения, изменившие быт","Почему люди любят страшные истории","Как устроены подземные города","Самые необычные профессии","Откуда появились названия улиц","Как свет влияет на атмосферу города","История настольных игр","Почему мы откладываем дела","Как создают кинематографический звук")
 fun createPodcast(program:RadioProgram,random:Random=Random.Default):String {
 val topic=topics.random(random)
 val opening=when(program.presenter){"max"->"С вами Макс. За окном ночь, самое время для историй, которые заставляют посмотреть на привычный мир иначе.";"maria"->"У микрофона Мария! Я приготовила тему, с которой можно отправиться в маленькое интеллектуальное путешествие.";else->"Это Алекс на NeiroFM. Давайте на несколько минут включим любопытство и разберём одну интересную тему."}
 val sections=listOf(
 "$opening Сегодня говорим о теме «$topic». И начнём не с энциклопедического определения, а с простого наблюдения из повседневной жизни.",
 "Попробуйте вспомнить, когда вы в последний раз сталкивались с этим явлением. Возможно, вы даже не обратили внимания: оно настолько привычно, что кажется частью фона. Но стоит задать один дополнительный вопрос — и за обычной картиной появляется целый мир причин, решений и неожиданных деталей.",
 "У подобных историй почти всегда несколько слоёв. Первый — то, что мы видим непосредственно. Второй — процессы, которые остаются за кадром. И третий — человеческий фактор: любопытство, ошибки, случайные открытия и желание сделать что-то немного лучше, чем вчера.",
 "Есть интересный способ взглянуть на тему иначе: представить, что вы объясняете её человеку, который никогда с ней не сталкивался. Какие детали вы назовёте первыми? Что покажется ему самым удивительным? Именно такие вопросы помогают отделить действительно важное от привычных слов.",
 "А теперь небольшое мысленное упражнение. В течение ближайшего дня попробуйте заметить один пример этой темы вокруг себя. Не нужно ничего специально искать или проверять — достаточно обратить внимание на деталь, мимо которой обычно проходите. Иногда так и начинаются самые интересные открытия.",
 "И ещё одна мысль напоследок: большие изменения часто начинаются не с громких событий, а с маленького вопроса, который кто-то однажды не побоялся задать. Пусть этот выпуск станет поводом задать свой вопрос.",
 "Это был авторский разговор NeiroFM — «$topic». У микрофона ${program.presenter}. Спасибо, что слушаете. Оставайтесь на нашей волне: дальше музыка и новые истории.")
 return sections.joinToString("\n\n")
 }
}
